before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>

int main()
{
    int score{3};
    int* observer = &score;
    if (observer != nullptr)
    {
        std::cout << *observer << "\n";
    }
    else
    {
        std::cout << "No target; original: " << score << "\n";
    }
}

```

